  { const f0 = dr_recitA('dr_heureDe'); if (f0) { try { const o = f0(h); if (o && o.base != null) return { jour: o.jour || dr_recitJourDe(o.base), debut: o.debut || dr_recitHm(o.base), fin: o.fin || '', base: o.base }; } catch (e) {} } }   /* l'interface d'E1/E2 (audit E2, C1) quand elle est là */
