function suiteDepuis(h){ /* ce que le site a composé depuis la prise de plume (les paragraphes des activités vues après) */ const t = (S.recitMoiT || {})[h]; if (!t) return ''; const html = troisTemps(recitHtml0(now(), h), h, now(), t); if (!html) return ''; const d = document.createElement('div'); d.innerHTML = html; const r = d.querySelector('.recit'); const ps = r ? Array.from(r.querySelectorAll(':scope > p')).filter(x => !x.classList.contains('cadre') && !x.classList.contains('sous') && !x.classList.contains('devoirs') && !x.classList.contains('bilan')) : []; return ps.map(x => x.outerHTML).join(''); }
